  emitProgressCheckpoint(reason = "periodic") {
    if (!this.runtimeSessionId) {
      return;
    }
    const now = Date.now();
    this.lastCheckpointAt = now;
    const elapsedSeconds = this.sessionStartedAt ? Math.max(
      0,
      Math.round(
        (now - this.sessionStartedAt) / 1e3
      )
    ) : 0;
    if (this.runtimeContext && typeof this.runtimeContext === "object") {
      this.runtimeContext.session = this.runtimeContext.session || {};
      this.runtimeContext.session.state = this.runtimeContext.session.state || {};
      this.runtimeContext.session.state.elapsedSeconds = elapsedSeconds;
      this.runtimeContext.session.state.checkpointReason = reason;
      this.runtimeContext.session.state.lastCheckpointAt = new Date(
        now
      ).toISOString();
    }
    this.dispatchRuntimeEvent(
      "nexivra-progress-checkpoint",
      {
        sessionId: this.runtimeSessionId,
        reason,
        checkpointAt: new Date(
          now
        ).toISOString(),
        elapsedSeconds,
        courseId: this.subjectId || null,
        moduleId: this.lessonId || null,
        trainingStage: this.runtimeContext?.session?.state?.stage || this.runtimeContext?.stage || "teaching",
        observationCount: this.observationTimeline.length,
        learnerVoiceTurnCount: this.learnerVoiceTurnCount,
        coachVoiceTurnCount: this.coachVoiceTurnCount
      }
    );
  }
